{
  "name": "myrealtrip-traveler-guard",
  "version": "1.0.0",
  "description": "여행상품 취소·환불 약관과 가격표시 다크패턴을 릴리스 전에 결정론적으로 검사하는 소비자보호 린트 스위트",
  "author": {
    "name": "AX 인재전쟁 마이리얼트립 팀"
  },
  "keywords": [
    "travel",
    "consumer-protection",
    "refund-policy",
    "dark-pattern",
    "compliance-lint"
  ],
  "skills": "./skills/"
}

{
  "meta": {
    "title": "국내외 여행·숙박 취소·환불 위약금 상한 기준 (소비자분쟁해결기준)",
    "authority": "공정거래위원회 고시 「소비자분쟁해결기준」 및 여행 표준약관",
    "version": "2025-07 스냅샷",
    "sources": [
      {
        "name": "소비자분쟁해결기준 (국가법령정보센터 행정규칙)",
        "url": "https://www.law.go.kr/행정규칙/소비자분쟁해결기준"
      },
      {
        "name": "찾기쉬운 생활법령정보 — 국외여행 취소 위약금",
        "url": "https://easylaw.go.kr/CSP/CnpClsMain.laf?ccfNo=2&cciNo=3&cnpClsNo=3&csmSeq=894&popMenu=ov"
      },
      {
        "name": "한국여행업협회 여행정보센터 — 소비자분쟁해결기준(여행)",
        "url": "http://www.tourinfo.or.kr/v2/info/resolution_02.asp"
      }
    ],
    "note": "penalty_pct(소비자 위약금 부담)의 '상한'을 카테고리별로 수록한다. days_before = 여행개시일(숙박은 사용예정일)까지 남은 일수. 어떤 취소 시점 tier의 penalty_pct가 그 시점이 속한 구간의 max_penalty_pct를 초과하면 소비자에게 불리(=위반). 이 기준은 '조정결정 불수용=위법'이라는 프레이밍이 아니라, 공개 고시 대비 정량 초과라는 근거로만 사용한다."
  },
  "categories": {
    "overseas_package": {
      "label": "국외여행 (여행사 주최 패키지)",
      "applicable": true,
      "source_url": "https://easylaw.go.kr/CSP/CnpClsMain.laf?ccfNo=2&cciNo=3&cnpClsNo=3&csmSeq=894&popMenu=ov",
      "brackets": [
        {"min_days_before": 30, "max_penalty_pct": 0,  "desc": "여행개시 30일 전까지 통보: 계약금 환급(위약금 0%)"},
        {"min_days_before": 20, "max_penalty_pct": 10, "desc": "20일 전까지 통보: 여행요금의 10%"},
        {"min_days_before": 10, "max_penalty_pct": 15, "desc": "10일 전까지 통보: 여행요금의 15%"},
        {"min_days_before": 8,  "max_penalty_pct": 20, "desc": "8일 전까지 통보: 여행요금의 20%"},
        {"min_days_before": 1,  "max_penalty_pct": 30, "desc": "1일 전까지 통보: 여행요금의 30%"},
        {"min_days_before": 0,  "max_penalty_pct": 50, "desc": "여행 당일 통보: 여행요금의 50%"}
      ]
    },
    "domestic_package": {
      "label": "국내여행 (여행사 주최, 숙박 포함)",
      "applicable": true,
      "source_url": "http://www.tourinfo.or.kr/v2/info/resolution_02.asp",
      "brackets": [
        {"min_days_before": 3, "max_penalty_pct": 0,  "desc": "여행개시 3일 전까지 통보: 계약금 환급(위약금 0%)"},
        {"min_days_before": 2, "max_penalty_pct": 10, "desc": "2일 전까지 통보: 여행요금의 10%"},
        {"min_days_before": 1, "max_penalty_pct": 20, "desc": "1일 전까지 통보: 여행요금의 20%"},
        {"min_days_before": 0, "max_penalty_pct": 30, "desc": "여행 당일 통보: 여행요금의 30%"}
      ]
    },
    "accommodation": {
      "label": "숙박 (비수기 주중 대표 기준)",
      "applicable": true,
      "source_url": "https://www.law.go.kr/행정규칙/소비자분쟁해결기준",
      "note": "숙박업 기준은 성수기/비수기 × 주중/주말로 세분된다. 본 baseline은 '비수기 주중' 대표값이며 성수기·주말은 상한이 더 높으므로 별도 검토가 필요하다.",
      "amendment_note": "2024.12 개정: 숙박 예약 후 24시간 이내 취소 시 위약금 면제(적용 조건 확인 필요). 출처: https://news.nate.com/view/20241227n13342",
      "brackets": [
        {"min_days_before": 2, "max_penalty_pct": 0,  "desc": "사용예정일 2일 전까지 취소: 계약금 환급"},
        {"min_days_before": 1, "max_penalty_pct": 10, "desc": "1일 전 취소: 총요금의 10% 공제"},
        {"min_days_before": 0, "max_penalty_pct": 20, "desc": "당일 취소·미이용: 총요금의 20% 공제"}
      ]
    },
    "air_ticket": {
      "label": "항공권 (개별 항공권)",
      "applicable": false,
      "source_url": "https://www.traveltimes.co.kr/news/articleView.html?idxno=404659",
      "reason": "항공권 취소·환불은 항공사 운임규정(IATA/개별 운임)과 여행사 취급수수료가 우선 적용되어, 소비자분쟁해결기준의 국외여행 위약금 상한을 그대로 적용하면 거짓양성이 발생한다. 따라서 본 린터는 항공권을 '기준 미적용(N/A)'으로 표시하고, 발권·취급·환불 수수료 투명성은 별도 검토 대상으로 남긴다."
    }
  }
}

{
  "meta": {
    "title": "여행상품 가격표시 다크패턴 유형 매핑 (공정위·한국소비자원 기준)",
